    fraud_str = fraud_str.strip()

    if '%' in fraud_str:
        fraud_str = fraud_str.replace('%', '')

    if '-' in fraud_str:
        parts = fraud_str.split('-')
        return (float(parts[0].strip()), float(parts[1].strip()))
    else:
        val = float(fraud_str)
