    """Parse volume string like '100k-1m', '>5m', '<100k' to comparison function"""
    if not volume_str:
        return None

    volume_str = volume_str.strip()

    def parse_value(s):
        s = s.strip()
        multipliers = {'k': 1000, 'm': 1000000}
        for suffix, mult in multipliers.items():
            if s.lower().endswith(suffix):
                return float(s[:-1]) * mult
        return float(s)

    if '-' in volume_str and not volume_str.startswith('-'):  # two-sided range
        parts = volume_str.split('-')
        low = parse_value(parts[0])
        high = parse_value(parts[1])
        return (low, high, 'range')
    elif volume_str.startswith('>'):
        return (parse_value(volume_str[1:]), None, 'greater')
    elif volume_str.startswith('<'):
        return (parse_value(volume_str[1:]), None, 'less')
    else:
        val = parse_value(volume_str)
        return (val, val, 'range')

