    """Check if value is in range specification"""
    if not range_spec:
        return True

    if range_spec[2] == 'range':
        return range_spec[0] <= value <= range_spec[1]
    elif range_spec[2] == 'greater':
        return value > range_spec[0]
    elif range_spec[2] == 'less':
        return value < range_spec[0]

    return True

